-- `ON CONFLICT … WHERE` restating a unique partial index's predicate matches it when
-- the predicate is a long `AND` list — with a parenthesized long list inside it too:
-- the restated text builds the tree the stored one is.
-- @setup
CREATE TABLE ocl (a INT, b INT);
CREATE UNIQUE INDEX ocl_long ON ocl (a) WHERE a <> 1000 AND a <> 1001 AND a <> 1002 AND a <> 1003 AND a <> 1004 AND a <> 1005 AND a <> 1006 AND a <> 1007 AND a <> 1008 AND a <> 1009 AND a <> 1010 AND a <> 1011 AND a <> 1012 AND a <> 1013 AND a <> 1014 AND a <> 1015 AND a <> 1016 AND a <> 1017 AND a <> 1018 AND a <> 1019 AND a <> 1020 AND a <> 1021 AND a <> 1022 AND a <> 1023 AND a <> 1024 AND a <> 1025 AND a <> 1026 AND a <> 1027 AND a <> 1028 AND a <> 1029 AND a <> 1030 AND a <> 1031 AND a <> 1032 AND a <> 1033 AND a <> 1034 AND a <> 1035 AND a <> 1036 AND a <> 1037 AND a <> 1038 AND a <> 1039 AND a <> 1040 AND a <> 1041 AND a <> 1042 AND a <> 1043 AND a <> 1044 AND a <> 1045 AND a <> 1046 AND a <> 1047 AND a <> 1048 AND a <> 1049 AND a <> 1050 AND a <> 1051 AND a <> 1052 AND a <> 1053 AND a <> 1054 AND a <> 1055 AND a <> 1056 AND a <> 1057 AND a <> 1058 AND a <> 1059 AND a <> 1060 AND a <> 1061 AND a <> 1062 AND a <> 1063 AND a <> 1064 AND a <> 1065 AND a <> 1066 AND a <> 1067 AND a <> 1068 AND a <> 1069 AND a <> 1070 AND a <> 1071 AND a <> 1072 AND a <> 1073 AND a <> 1074 AND a <> 1075 AND a <> 1076 AND a <> 1077 AND a <> 1078 AND a <> 1079 AND a <> 1080 AND a <> 1081 AND a <> 1082 AND a <> 1083 AND a <> 1084 AND a <> 1085 AND a <> 1086 AND a <> 1087 AND a <> 1088 AND a <> 1089 AND a <> 1090 AND a <> 1091 AND a <> 1092 AND a <> 1093 AND a <> 1094 AND a <> 1095 AND a <> 1096 AND a <> 1097 AND a <> 1098 AND a <> 1099;
CREATE TABLE ocm (a INT, b INT);
CREATE UNIQUE INDEX ocm_nested ON ocm (a) WHERE a <> 0 AND a <> 1 AND a <> 2 AND a <> 3 AND a <> 4 AND a <> 5 AND a <> 6 AND a <> 7 AND a <> 8 AND a <> 9 AND a <> 10 AND a <> 11 AND a <> 12 AND a <> 13 AND a <> 14 AND a <> 15 AND a <> 16 AND a <> 17 AND a <> 18 AND a <> 19 AND a <> 20 AND a <> 21 AND a <> 22 AND a <> 23 AND a <> 24 AND a <> 25 AND a <> 26 AND a <> 27 AND a <> 28 AND a <> 29 AND a <> 30 AND a <> 31 AND a <> 32 AND a <> 33 AND a <> 34 AND (a <> 100 AND a <> 101 AND a <> 102 AND a <> 103 AND a <> 104 AND a <> 105 AND a <> 106 AND a <> 107 AND a <> 108 AND a <> 109 AND a <> 110 AND a <> 111 AND a <> 112 AND a <> 113 AND a <> 114 AND a <> 115 AND a <> 116 AND a <> 117 AND a <> 118 AND a <> 119 AND a <> 120 AND a <> 121 AND a <> 122 AND a <> 123 AND a <> 124 AND a <> 125 AND a <> 126 AND a <> 127 AND a <> 128 AND a <> 129 AND a <> 130 AND a <> 131 AND a <> 132 AND a <> 133 AND a <> 134 AND a <> 135 AND a <> 136 AND a <> 137 AND a <> 138 AND a <> 139 AND a <> 140 AND a <> 141 AND a <> 142 AND a <> 143 AND a <> 144 AND a <> 145 AND a <> 146 AND a <> 147 AND a <> 148 AND a <> 149 AND a <> 150 AND a <> 151 AND a <> 152 AND a <> 153 AND a <> 154 AND a <> 155 AND a <> 156 AND a <> 157 AND a <> 158 AND a <> 159 AND a <> 160 AND a <> 161 AND a <> 162 AND a <> 163 AND a <> 164 AND a <> 165 AND a <> 166 AND a <> 167 AND a <> 168 AND a <> 169) AND a <> 35 AND a <> 36 AND a <> 37 AND a <> 38 AND a <> 39 AND a <> 40 AND a <> 41 AND a <> 42 AND a <> 43 AND a <> 44 AND a <> 45 AND a <> 46 AND a <> 47 AND a <> 48 AND a <> 49 AND a <> 50 AND a <> 51 AND a <> 52 AND a <> 53 AND a <> 54 AND a <> 55 AND a <> 56 AND a <> 57 AND a <> 58 AND a <> 59 AND a <> 60 AND a <> 61 AND a <> 62 AND a <> 63 AND a <> 64 AND a <> 65 AND a <> 66 AND a <> 67 AND a <> 68 AND a <> 69;
INSERT INTO ocl VALUES (1, 1);
INSERT INTO ocm VALUES (500, 1);
-- @test
INSERT INTO ocl VALUES (1, 2) ON CONFLICT (a) WHERE a <> 1000 AND a <> 1001 AND a <> 1002 AND a <> 1003 AND a <> 1004 AND a <> 1005 AND a <> 1006 AND a <> 1007 AND a <> 1008 AND a <> 1009 AND a <> 1010 AND a <> 1011 AND a <> 1012 AND a <> 1013 AND a <> 1014 AND a <> 1015 AND a <> 1016 AND a <> 1017 AND a <> 1018 AND a <> 1019 AND a <> 1020 AND a <> 1021 AND a <> 1022 AND a <> 1023 AND a <> 1024 AND a <> 1025 AND a <> 1026 AND a <> 1027 AND a <> 1028 AND a <> 1029 AND a <> 1030 AND a <> 1031 AND a <> 1032 AND a <> 1033 AND a <> 1034 AND a <> 1035 AND a <> 1036 AND a <> 1037 AND a <> 1038 AND a <> 1039 AND a <> 1040 AND a <> 1041 AND a <> 1042 AND a <> 1043 AND a <> 1044 AND a <> 1045 AND a <> 1046 AND a <> 1047 AND a <> 1048 AND a <> 1049 AND a <> 1050 AND a <> 1051 AND a <> 1052 AND a <> 1053 AND a <> 1054 AND a <> 1055 AND a <> 1056 AND a <> 1057 AND a <> 1058 AND a <> 1059 AND a <> 1060 AND a <> 1061 AND a <> 1062 AND a <> 1063 AND a <> 1064 AND a <> 1065 AND a <> 1066 AND a <> 1067 AND a <> 1068 AND a <> 1069 AND a <> 1070 AND a <> 1071 AND a <> 1072 AND a <> 1073 AND a <> 1074 AND a <> 1075 AND a <> 1076 AND a <> 1077 AND a <> 1078 AND a <> 1079 AND a <> 1080 AND a <> 1081 AND a <> 1082 AND a <> 1083 AND a <> 1084 AND a <> 1085 AND a <> 1086 AND a <> 1087 AND a <> 1088 AND a <> 1089 AND a <> 1090 AND a <> 1091 AND a <> 1092 AND a <> 1093 AND a <> 1094 AND a <> 1095 AND a <> 1096 AND a <> 1097 AND a <> 1098 AND a <> 1099 DO UPDATE SET b = excluded.b;
INSERT INTO ocm VALUES (500, 3) ON CONFLICT (a) WHERE a <> 0 AND a <> 1 AND a <> 2 AND a <> 3 AND a <> 4 AND a <> 5 AND a <> 6 AND a <> 7 AND a <> 8 AND a <> 9 AND a <> 10 AND a <> 11 AND a <> 12 AND a <> 13 AND a <> 14 AND a <> 15 AND a <> 16 AND a <> 17 AND a <> 18 AND a <> 19 AND a <> 20 AND a <> 21 AND a <> 22 AND a <> 23 AND a <> 24 AND a <> 25 AND a <> 26 AND a <> 27 AND a <> 28 AND a <> 29 AND a <> 30 AND a <> 31 AND a <> 32 AND a <> 33 AND a <> 34 AND (a <> 100 AND a <> 101 AND a <> 102 AND a <> 103 AND a <> 104 AND a <> 105 AND a <> 106 AND a <> 107 AND a <> 108 AND a <> 109 AND a <> 110 AND a <> 111 AND a <> 112 AND a <> 113 AND a <> 114 AND a <> 115 AND a <> 116 AND a <> 117 AND a <> 118 AND a <> 119 AND a <> 120 AND a <> 121 AND a <> 122 AND a <> 123 AND a <> 124 AND a <> 125 AND a <> 126 AND a <> 127 AND a <> 128 AND a <> 129 AND a <> 130 AND a <> 131 AND a <> 132 AND a <> 133 AND a <> 134 AND a <> 135 AND a <> 136 AND a <> 137 AND a <> 138 AND a <> 139 AND a <> 140 AND a <> 141 AND a <> 142 AND a <> 143 AND a <> 144 AND a <> 145 AND a <> 146 AND a <> 147 AND a <> 148 AND a <> 149 AND a <> 150 AND a <> 151 AND a <> 152 AND a <> 153 AND a <> 154 AND a <> 155 AND a <> 156 AND a <> 157 AND a <> 158 AND a <> 159 AND a <> 160 AND a <> 161 AND a <> 162 AND a <> 163 AND a <> 164 AND a <> 165 AND a <> 166 AND a <> 167 AND a <> 168 AND a <> 169) AND a <> 35 AND a <> 36 AND a <> 37 AND a <> 38 AND a <> 39 AND a <> 40 AND a <> 41 AND a <> 42 AND a <> 43 AND a <> 44 AND a <> 45 AND a <> 46 AND a <> 47 AND a <> 48 AND a <> 49 AND a <> 50 AND a <> 51 AND a <> 52 AND a <> 53 AND a <> 54 AND a <> 55 AND a <> 56 AND a <> 57 AND a <> 58 AND a <> 59 AND a <> 60 AND a <> 61 AND a <> 62 AND a <> 63 AND a <> 64 AND a <> 65 AND a <> 66 AND a <> 67 AND a <> 68 AND a <> 69 DO UPDATE SET b = excluded.b;
SELECT 'l' AS t, a, b FROM ocl UNION ALL SELECT 'm', a, b FROM ocm ORDER BY t;
